using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json.Linq;
using TMPro;
using UnityEngine;
namespace LastRail.Presentation.MissionShell {public sealed partial class LobbyCommandDeck {
 bool bulkDialog,bulkResults,passAllResults;int bulkPage;BulkClaimSelection bulkSelection;readonly List<string> bulkSelected=new List<string>();
 public void OpenBulkSelection(string kind,string policy=null,string track=null){if(accountState==null)return;if(accountState.Pending?.Kind=="recurring-bulk"){OpenBulkResults();return;}var selection=accountState.PrepareBulkSelection(kind,policy,track);if(selection==null){ShowInfo("선택 수령","최신 보상 상태와 이전 요청 결과를 먼저 확인해 주세요.");return;}ShowInfo("선택 수령","");bulkDialog=true;bulkResults=false;bulkSelection=selection;bulkPage=0;bulkSelected.Clear();PrepareBulkDialog();DrawBulk();}
 void OpenBulkTracks(string policy){if(accountState?.Pending?.Kind=="recurring-bulk"){OpenBulkResults();return;}ShowInfo("패스 선택 수령","수령할 보상 종류를 선택하세요.");Button("BulkFree",dialog,60,400,630,75,"무료 보상",()=>OpenBulkSelection("PASS_LEVEL",policy,"FREE"));Button("BulkPremium",dialog,60,500,630,75,"프리미엄 보상",()=>OpenBulkSelection("PASS_LEVEL",policy,"PREMIUM"));}
 public void OpenBulkResults(){passAllResults=false;ShowInfo("수령 결과","");bulkDialog=true;bulkResults=true;bulkPage=0;PrepareBulkDialog();DrawBulk();}
 void OpenPassClaimAllResults(){OpenBulkResults();passAllResults=true;DrawBulk();}
 void PrepareBulkDialog(){dialog.sizeDelta=new Vector2(750,1240);dialog.Find("DialogBody").gameObject.SetActive(false);Place(dialog.Find("CloseLobbyDialog").GetComponent<RectTransform>(),60,1140,630,65);EvaluateLayout();}
 void BulkChanged(){if(!bulkDialog||dialog==null)return;if(!bulkResults&&!accountState.IsBulkSelectionCurrent(bulkSelection)){CloseDialog();return;}if(bulkResults&&!passAllResults&&accountState?.LastBulkResult==null&&accountState?.Pending?.Kind!="recurring-bulk"&&string.IsNullOrEmpty(accountState?.BulkNotice)){CloseDialog();return;}DrawBulk();}
 void DrawBulk(){if(!bulkDialog||dialog==null)return;var old=dialog.Find("BulkContent");if(old!=null){old.gameObject.SetActive(false);old.name="RetiredBulk";if(Application.isPlaying)Destroy(old.gameObject);else DestroyImmediate(old.gameObject);}var area=Rect("BulkContent",dialog);Place(area,0,0,750,1130);var state=accountState;var result=state?.LastBulkResult;var rows=passAllResults?state?.PassClaimAllItems??new JArray():bulkResults?result?.Items??new JArray():bulkSelection.Rows;int pages=Math.Max(1,(rows.Count+4)/5);bulkPage=Math.Min(bulkPage,pages-1);
  Label("BulkSummary",area,passAllResults?state?.PassClaimAllNotice??"":bulkResults?(string.IsNullOrEmpty(state?.BulkNotice)?"요청 결과를 확인해 주세요.":state.BulkNotice):"받을 보상을 선택하세요.\n선택 "+bulkSelected.Count+" / "+rows.Count,40,135,670,105,27,TextAlignmentOptions.Center);
  if(rows.Count==0)Label("BulkEmpty",area,bulkResults?"아직 확인된 항목이 없습니다.\n이어받기로 원래 요청을 확인하세요.":"지금 수령할 수 있는 보상이 없습니다.",40,315,670,150,27,TextAlignmentOptions.Center);
  for(int i=0;i<5;i++){int index=bulkPage*5+i;if(index>=rows.Count)break;var row=(JObject)rows[index];float y=260+i*133;if(!bulkResults){var id=(string)row["id"];var button=Button("BulkSelect"+index,area,40,y,670,116,(bulkSelected.Contains(id)?"✓  ":"□  ")+(string)row["label"],()=>{if(bulkSelected.Contains(id))bulkSelected.Remove(id);else if(bulkSelected.Count<50)bulkSelected.Add(id);DrawBulk();});button.GetComponentInChildren<TMP_Text>().fontSize=23;button.interactable=state!=null&&!state.Busy;}
   else{var action=(JObject)row["action"];var kind=(string)action["kind"];var status=(string)row["status"];var caption=kind=="PASS_LEVEL"?"Lv."+(int)action["level"]+" · "+((string)action["track"]=="FREE"?"무료":"프리미엄"):(kind=="MAIL"?"우편 보상 ":"임무 보상 ")+(index+1);var detail=status=="SUCCESS"?"수령 완료":status=="REPLAYED"?"기존 수령 확인":status=="FAILED"?"실패 · "+BulkError((string)row["errorCode"]):"미확정 · 이어받기 필요";if(row["receipt"] is JObject receipt)detail+="\n"+RecurringContract.RewardText((JArray)receipt["rewardLines"]);Label("BulkItem"+index,area,caption+"\n"+detail,50,y,650,123,23,TextAlignmentOptions.MidlineLeft);}}
  Button("BulkPrevious",area,40,935,190,55,"‹",()=>{bulkPage=(bulkPage+pages-1)%pages;DrawBulk();});Label("BulkPage",area,(bulkPage+1)+" / "+pages,250,935,250,55,25,TextAlignmentOptions.Center);Button("BulkNext",area,520,935,190,55,"›",()=>{bulkPage=(bulkPage+1)%pages;DrawBulk();});
  if(!bulkResults){var all=Button("BulkSelectAll",area,40,1010,325,80,bulkSelected.Count==rows.Count&&rows.Count>0?"선택 해제":"모두 선택",()=>{if(bulkSelected.Count==rows.Count)bulkSelected.Clear();else{bulkSelected.Clear();bulkSelected.AddRange(rows.Take(50).Select(r=>(string)r["id"]));}DrawBulk();});all.interactable=rows.Count>0&&state!=null&&!state.Busy;var submit=Button("BulkConfirm",area,385,1010,325,80,bulkSelected.Count+"개 수령",async()=>{var command=state.PrepareBulkCommand(bulkSelection,bulkSelected);if(command==null)return;OpenBulkResults();await state.SubmitBulkAsync(command);});submit.interactable=bulkSelected.Count>0&&state!=null&&!state.Busy;}
  else if(passAllResults){var resume=Button("PassAllContinue",area,40,1010,670,80,state?.CanContinuePassClaimAll==true?"이어받기":"처리 완료",async()=>await state.ContinuePassClaimAllAsync());resume.interactable=state?.CanContinuePassClaimAll==true;}
  else{var read=Button("BulkRead",area,40,1010,325,80,"기록 조회",async()=>await state.RefreshBulkResultAsync());read.interactable=result!=null&&state!=null&&!state.Busy&&!state.BulkReading;var resume=Button("BulkContinue",area,385,1010,325,80,state?.Pending?.Kind=="recurring-bulk"?"이어받기":"처리 완료",async()=>await state.ContinueBulkAsync());resume.interactable=state?.Pending?.Kind=="recurring-bulk"&&!state.Busy&&!state.BulkReading;}
 }
 static string BulkError(string code){if(code==null)return "조건 확인 필요";if(code.Contains("expired"))return "수령 기한 만료";if(code.Contains("premium"))return "프리미엄 보유 필요";if(code.Contains("earned")||code.Contains("level"))return "진행 조건 미달";if(code.Contains("not_found"))return "보상 확인 불가";return "수령 조건 미충족";}
} }
